method concatenate(strings: seq<string>) returns (result: string)
    requires strings != null
    ensures result == String.Concat(strings)
    ensures |strings| == 0 ==> result == ""
    ensures |strings| > 0 ==> result == String.Concat(strings)
{
    var sb := new StringBuilder();
    var i := 0;
    while i < |strings|
        invariant 0 <= i <= |strings|
        invariant sb.ToString() == String.Concat(strings[0..i])
    {
        sb.Append(strings[i]);
        i := i + 1;
    }
    result := sb.ToString();
}
```

